use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let input_map = input.as_object().unwrap();
    let shift = input_map["shift"].as_i64().unwrap();
    let text = input_map["text"].as_str().unwrap();

    let result = text.chars().map(|c| {
        if c.is_ascii_lowercase() {
            let base = 'a' as i64;
            let offset = (c as i64 - base + shift) % 26;
            (base + offset) as u8 as char
        } else {
            c
        }
    }).collect::<String>();

    Value::String(result)
}
